"""Execute one customer payout through the external bank-transfer provider.

Design: each payout gets at most one provider.send, ever.

- The RESERVED -> SENDING compare-and-swap is the only route to send. It lets
  one invocation win, and it durably records send_attempted_at before the
  provider is called. A worker killed after the claim leaves a SENDING row,
  which is treated as "may have landed".
- All other invocations only use lookup, which cannot move money. The 24-hour
  send idempotency window is deliberately not relied on, so there is no
  reference-expiry path to a second transfer. A worker paused for any length
  of time cannot cause one either.
- send_attempted_at is written once, by the claim winner, so it cannot regress
  and is always the most recent send attempt.

Trade-off: a send that never landed (timeout, or a kill before the call)
becomes FAILED after 900 seconds instead of being retried. The held funds are
released, and the payout can be reissued under a new payout_id.

Residual risk: a worker can stall after its final status check and call send
more than 900 seconds after its claim, or be given a stale `now`. The payout
may then be FAILED before the transfer lands. The provider has no fencing
mechanism, so this cannot be fully closed here. The re-read before send keeps
the window small, and a stalled worker that sees the transfer accepted logs a
critical error for reconciliation. The destination is still paid only once.
"""

import logging

ProviderTimeout = TimeoutError

logger = logging.getLogger(__name__)

RESERVED = "RESERVED"
SENDING = "SENDING"
PAID = "PAID"
FAILED = "FAILED"
PENDING = "PENDING"
INSUFFICIENT = "INSUFFICIENT"

LOOKUP_VISIBILITY_SECONDS = 900

_OUTCOME_BY_PROVIDER_STATUS = {"accepted": PAID, "rejected": FAILED}


def _current_status(store, payout_id):
    """Return the caller-facing status from a fresh read of the stored row."""
    status = store.get_payout(payout_id)["status"]
    return status if status in (PAID, FAILED) else PENDING


def _record_result(store, payout_id, result):
    """Apply a provider result and return the true stored status."""
    outcome = _OUTCOME_BY_PROVIDER_STATUS.get(result.get("status"))
    if outcome is None:
        # An unrecognised status proves nothing, so keep the funds held.
        return _current_status(store, payout_id)

    store.finish(
        payout_id,
        SENDING,
        outcome,
        provider_id=result.get("provider_id"),
    )
    status = _current_status(store, payout_id)
    if outcome == PAID and status == FAILED:
        logger.critical(
            "Payout %s is FAILED but the provider accepted it; "
            "manual reconciliation required",
            payout_id,
        )
    return status


def _send_once(store, provider, payout_id):
    """Make the single send for a payout. Only the claim winner calls this."""
    row = store.get_payout(payout_id)
    if row["status"] != SENDING:
        # Another invocation finished the payout while this worker was stalled.
        return _current_status(store, payout_id)

    try:
        result = provider.send(payout_id, row["dest"], row["amount_minor"])
    except ProviderTimeout:
        return _current_status(store, payout_id)
    return _record_result(store, payout_id, result)


def _reconcile(store, provider, payout_id, row, now):
    """Resolve a SENDING payout without any call that could move money."""
    try:
        result = provider.lookup(payout_id)
    except ProviderTimeout:
        return _current_status(store, payout_id)

    if result is not None:
        return _record_result(store, payout_id, result)

    if now - row["send_attempted_at"] >= LOOKUP_VISIBILITY_SECONDS:
        store.finish(payout_id, SENDING, FAILED)
    return _current_status(store, payout_id)


def execute_payout(store, provider, payout_id, account, amount_minor, dest, now) -> str:
    """Returns the payout's current status: "PAID", "FAILED", "PENDING" or "INSUFFICIENT"."""
    row = store.get_payout(payout_id)
    if row is None:
        if store.reserve(payout_id, account, amount_minor, dest) == INSUFFICIENT:
            return INSUFFICIENT
        row = store.get_payout(payout_id)

    if row["status"] == RESERVED:
        if store.update(payout_id, RESERVED, SENDING, send_attempted_at=now):
            return _send_once(store, provider, payout_id)
        row = store.get_payout(payout_id)

    if row["status"] == SENDING:
        return _reconcile(store, provider, payout_id, row, now)

    return _current_status(store, payout_id)
